async function buildWorkspace() {
  // 1. Get or create Workspace page
  let wsPage = figma.root.children.find(c => c.name.includes("03 · Workspace"));
  if (!wsPage) {
    wsPage = figma.createPage();
    wsPage.name = "03 · Workspace";
  }
  await figma.setCurrentPageAsync(wsPage);

  // Clear existing content in workspace page if re-running
  for (const child of wsPage.children) {
    child.remove();
  }

  // Load Poppins fonts
  await figma.loadFontAsync({ family: "Poppins", style: "Regular" });
  await figma.loadFontAsync({ family: "Poppins", style: "Medium" });
  await figma.loadFontAsync({ family: "Poppins", style: "Semi Bold" });
  await figma.loadFontAsync({ family: "Poppins", style: "Bold" });

  // Get source components from Media and Components pages
  const mediaPage = figma.root.children.find(c => c.name.includes("04 · Media"));
  const getMediaComp = (name) => mediaPage.findOne(n => n.name === name && n.type === "COMPONENT");

  const logoABM = getMediaComp("Logo_ABM");
  const photoAvatar = getMediaComp("Photo_Avatar");
  const photoCSS = getMediaComp("Photo_Project_CSS");
  const photoHTML = getMediaComp("Photo_Project_HTML");

  const logoCSS3 = getMediaComp("Logo_CSS3");
  const logoHTML5 = getMediaComp("Logo_HTML5");
  const logoJS = getMediaComp("Logo_JavaScript");
  const logoNext = getMediaComp("Logo_Nextjs");
  const logoReact = getMediaComp("Logo_React");

  const logoInsta = getMediaComp("Logo_Instagram");
  const logoX = getMediaComp("Logo_X");
  const logoYT = getMediaComp("Logo_YouTube");

  const iconArrow = getMediaComp("Icon_Arrow_Up_Right");
  const iconMail = getMediaComp("Icon_Mail");

  // Colors
  const COLOR_BG = { r: 0.05, g: 0.05, b: 0.07 }; // #0D0D12
