  expSecTitle.fontName = { family: "Poppins", style: "Bold" };
  expSecTitle.fontSize = 32;
  expSecTitle.characters = "Experience";
  expSecTitle.fills = [{ type: 'SOLID', color: COLOR_TEXT_PRIMARY }];

  const expListContainer = figma.createFrame();
  expListContainer.name = "Experience List";
  expListContainer.layoutMode = "VERTICAL";
  expListContainer.itemSpacing = 24;
  expListContainer.layoutAlign = "STRETCH";
  expListContainer.fills = [];

  const expData = [
    {
      mark: "S",
      role: "Lead Software Engineer at Searchlight",
      date: "Nov 2019 – Present",
      desc: "As a Lead Software Engineer at Searchlight, I played a pivotal role in developing innovative solutions for Searchlight’s core search algorithms. Collaborating with a dynamic team of engineers, I contributed to the enhancement of search accuracy and efficiency, optimizing user experiences for millions of users worldwide."
    },
    {
      mark: "MS",
      role: "Software Engineer at Meridian Social",
      date: "Jan 2017 – Oct 2019",
      desc: "At Meridian Social, I served as a Software Engineer, focusing on the design and implementation of backend systems for the social media company’s dynamic platform. Working on projects that involved large-scale data processing and user engagement features, I leveraged my expertise to ensure seamless functionality and scalability."
    },
    {
      mark: "OC",
      role: "Junior Software Engineer at Orchard Computing",
      date: "Jan 2016 – Dec 2016",
      desc: "During my tenure at Orchard Computing, I worked as a Junior Software Engineer and contributed to the architecture of mission-critical software projects. I helped design scalable and efficient systems as part of a cross-functional team."
    }
  ];

  for (const exp of expData) {
    const entry = expCardComp.createInstance();
    const markNode = entry.findOne(n => n.name === "Initials");
    if (markNode) markNode.characters = exp.mark;
    const roleNode = entry.findOne(n => n.name === "Role & Company");
    if (roleNode) roleNode.characters = exp.role;
    const dateNode = entry.findOne(n => n.name === "Dates");
    if (dateNode) dateNode.characters = exp.date;
    const descNode = entry.findOne(n => n.name === "Description");
    if (descNode) descNode.characters = exp.desc;

    expListContainer.appendChild(entry);
  }

  expSection.appendChild(expSecTitle);
  expSection.appendChild(expListContainer);
  homeFrame.appendChild(expSection);

  // 6. CONTACT SECTION / FOOTER
  const contactFooter = figma.createFrame();
  contactFooter.name = "Contact Section";
  contactFooter.layoutMode = "VERTICAL";
  contactFooter.paddingLeft = 80;
  contactFooter.paddingRight = 80;
  contactFooter.paddingTop = 80;
  contactFooter.paddingBottom = 80;
  contactFooter.itemSpacing = 32;
  contactFooter.layoutAlign = "STRETCH";
  contactFooter.fills = [{ type: 'SOLID', color: COLOR_SURFACE }];
  contactFooter.strokes = [{ type: 'SOLID', color: COLOR_BORDER }];
  contactFooter.strokeWeight = 1;

  const contactTitle = figma.createText();
  contactTitle.name = "Section Title";
  contactTitle.fontName = { family: "Poppins", style: "Bold" };
  contactTitle.fontSize = 32;
  contactTitle.characters = "Contact";
  contactTitle.fills = [{ type: 'SOLID', color: COLOR_TEXT_PRIMARY }];

  const contactBio = figma.createText();
  contactBio.name = "Contact Bio";
  contactBio.fontName = { family: "Poppins", style: "Regular" };
  contactBio.fontSize = 18;
  contactBio.lineHeight = { value: 160, unit: 'PERCENT' };
  contactBio.characters = "Seasoned Full Stack Software Engineer with over 8 years of hands-on experience in designing and implementing robust, scalable, and innovative web solutions. Adept at leveraging a comprehensive skill set encompassing front-end and back-end technologies.";
  contactBio.fills = [{ type: 'SOLID', color: COLOR_TEXT_SECONDARY }];
  contactBio.layoutAlign = "STRETCH";

  const contactLinksRow = figma.createFrame();
  contactLinksRow.name = "Contact Links Row";
  contactLinksRow.layoutMode = "HORIZONTAL";
  contactLinksRow.layoutAlign = "STRETCH";
  contactLinksRow.primaryAxisAlignItems = "SPACE_BETWEEN";
  contactLinksRow.counterAxisAlignItems = "CENTER";
  contactLinksRow.fills = [];

  const emailBlock = figma.createFrame();
  emailBlock.name = "Email Link";
  emailBlock.layoutMode = "HORIZONTAL";
  emailBlock.itemSpacing = 12;
  emailBlock.counterAxisAlignItems = "CENTER";
  emailBlock.fills = [];

  if (iconMail) {
    const mailInst = iconMail.createInstance();
    recolorNode(mailInst, COLOR_ORANGE);
    emailBlock.appendChild(mailInst);
  }

  const emailText = figma.createText();
  emailText.name = "Email Text";
  emailText.fontName = { family: "Poppins", style: "Semi Bold" };
  emailText.fontSize = 18;
  emailText.characters = "abm@example.com";
  emailText.fills = [{ type: 'SOLID', color: COLOR_TEXT_PRIMARY }];
  emailBlock.appendChild(emailText);

  const socialBlock = figma.createFrame();
  socialBlock.name = "Social Links";
  socialBlock.layoutMode = "HORIZONTAL";
  socialBlock.itemSpacing = 16;
  socialBlock.fills = [];

  const socials = [
    { name: "Instagram", logo: logoInsta },
    { name: "X", logo: logoX },
    { name: "YouTube", logo: logoYT }
  ];

  for (const s of socials) {
    const sButton = figma.createFrame();
    sButton.name = `Social - ${s.name}`;
    sButton.resize(48, 48);
    sButton.cornerRadius = 24;
    sButton.fills = [{ type: 'SOLID', color: COLOR_BG }];
    sButton.strokes = [{ type: 'SOLID', color: COLOR_BORDER }];
    sButton.strokeWeight = 1;
    sButton.layoutMode = "HORIZONTAL";
    sButton.primaryAxisAlignItems = "CENTER";
    sButton.counterAxisAlignItems = "CENTER";

    if (s.logo) {
      const sInst = s.logo.createInstance();
      recolorNode(sInst, COLOR_TEXT_PRIMARY);
      sButton.appendChild(sInst);
    }
    socialBlock.appendChild(sButton);
  }

  contactLinksRow.appendChild(emailBlock);
  contactLinksRow.appendChild(socialBlock);

  contactFooter.appendChild(contactTitle);
  contactFooter.appendChild(contactBio);
  contactFooter.appendChild(contactLinksRow);

  homeFrame.appendChild(contactFooter);

  return `Frame 01_Home created with ID=${homeFrame.id}, Workspace Page ID=${wsPage.id}`;
}

return buildWorkspace();
